const updateClubVenue = `-- name: UpdateClubVenue :one
UPDATE club_venues
SET name = $1, address = $2, court_fee_per_court_hour_minor = $3,
    entrance_fee_minor = $4, revision = revision + 1, updated_at = $5
WHERE id = $6
RETURNING id, club_id, name, address, court_fee_per_court_hour_minor, entrance_fee_minor, currency, created_at, updated_at, revision
`

type UpdateClubVenueParams struct {
	Name                      string
	Address                   pgtype.Text
	CourtFeePerCourtHourMinor pgtype.Int4
	EntranceFeeMinor          pgtype.Int4
	Now                       pgtype.Timestamptz
	ID                        pgtype.UUID
}

func (q *Queries) UpdateClubVenue(ctx context.Context, arg UpdateClubVenueParams) (ClubVenue, error) {
	row := q.db.QueryRow(ctx, updateClubVenue,
		arg.Name,
		arg.Address,
		arg.CourtFeePerCourtHourMinor,
		arg.EntranceFeeMinor,
		arg.Now,
		arg.ID,
	)
	var i ClubVenue
	err := row.Scan(
		&i.ID,
		&i.ClubID,
		&i.Name,
		&i.Address,
		&i.CourtFeePerCourtHourMinor,
		&i.EntranceFeeMinor,
		&i.Currency,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Revision,
	)
	return i, err
}
